INSERT INTO diseases (id, name, description, symptoms, causes, preventions, treatment) VALUES 
('D001', 'Cảm lạnh thông thường', 'Cảm lạnh là một bệnh nhiễm trùng đường hô hấp trên do vi khuẩn gây ra.', 'Hắt hơi, sổ mũi, đau họng, ho, mệt mỏi.', 'Virus cảm lạnh lây lan qua tiếp xúc trực tiếp hoặc gián tiếp với người bệnh.', 'Rửa tay thường xuyên, tránh tiếp xúc gần với người bệnh, duy trì hệ miễn dịch khỏe mạnh.', 'Nghỉ ngơi, uống nhiều nước, sử dụng thuốc giảm triệu chứng như thuốc giảm đau và hạ sốt.'),
('D002', 'Cảm cúm', 'Bệnh nhiễm trùng đường hô hấp cấp tính do virus cúm (Influenza) gây ra, thường nặng hơn cảm lạnh.', 'Sốt cao đột ngột (thường trên 38.5°C), ớn lạnh, đau đầu dữ dội, đau mỏi cơ bắp nghiêm trọng, mệt mỏi kiệt sức, ho khan, đau họng.', 'Virus cúm nhóm A, B, C. Lây truyền qua giọt bắn đường hô hấp khi người bệnh ho, hắt hơi hoặc nói chuyện.', 'Tiêm vắc-xin phòng cúm hàng năm, rửa tay thường xuyên bằng xà phòng, che miệng khi ho/hắt hơi, tránh tụ tập nơi đông người khi có dịch.', 'Nghỉ ngơi, uống nhiều nước/chất điện giải. Dùng thuốc hạ sốt (Paracetamol, Ibuprofen). Bác sĩ có thể chỉ định thuốc kháng virus (như Oseltamivir) trong một số trường hợp.'),
('D003', 'Viêm họng và Viêm Amidan cấp', 'Tình trạng viêm, sưng, tấy đỏ ở niêm mạc họng và/hoặc amidan, gây đau rát.', 'Đau họng, rát họng, khó nuốt, amidan sưng đỏ (có thể có mủ trắng), sốt, sưng hạch cổ, hôi miệng.', 'Chủ yếu do virus (như virus cảm lạnh, cúm). Một số trường hợp do vi khuẩn (phổ biến là liên cầu khuẩn nhóm A - Streptococcus pyogenes).', 'Vệ sinh răng miệng sạch sẽ, súc họng bằng nước muối ấm, giữ ấm vùng cổ, rửa tay thường xuyên, tránh khói thuốc lá.', 'Uống nhiều nước ấm, súc họng nước muối. Dùng thuốc giảm đau, hạ sốt. Nếu nguyên nhân là vi khuẩn, bác sĩ sẽ kê đơn kháng sinh.'),
('D004', 'Viêm phế quản cấp', 'Tình trạng viêm nhiễm cấp tính của niêm mạc phế quản (đường dẫn khí lớn vào phổi), thường xảy ra sau một đợt cảm lạnh hoặc cúm.', 'Ho (thường là ho có đờm, đờm có thể màu trắng, vàng hoặc xanh), tức ngực, mệt mỏi, khó thở nhẹ, sốt nhẹ.', 'Hầu hết do virus (tương tự virus gây cảm lạnh, cúm). Một số ít do vi khuẩn hoặc hít phải chất kích ứng (khói thuốc, bụi, ô nhiễm).', 'Không hút thuốc lá, tránh xa khói thuốc và môi trường ô nhiễm, tiêm vắc-xin cúm hàng năm, rửa tay thường xuyên.', 'Nghỉ ngơi, uống nhiều nước. Dùng thuốc giảm ho (nếu ho khan gây khó chịu), thuốc long đờm. Máy tạo độ ẩm có thể giúp. Kháng sinh thường không cần thiết (trừ khi do vi khuẩn).'),
('D005', 'Bệnh Lao phổi', 'Bệnh truyền nhiễm do vi khuẩn Mycobacterium tuberculosis (M. tuberculosis) gây ra, chủ yếu tấn công phổi nhưng có thể ảnh hưởng đến các bộ phận khác.', 'Ho kéo dài (trên 2 tuần), ho ra máu, đau ngực, sốt về chiều, đổ mồ hôi đêm, sụt cân không rõ nguyên nhân, mệt mỏi.', 'Vi khuẩn M. tuberculosis lây truyền qua không khí khi người bệnh lao phổi ho, hắt hơi, khạc nhổ.', 'Tiêm vắc-xin BCG cho trẻ sơ sinh, che miệng khi ho/hắt hơi, đảm bảo môi trường sống thông thoáng, phát hiện và điều trị sớm cho người bệnh.', 'Điều trị bằng phác đồ kháng sinh đặc hiệu (thường kéo dài từ 6 tháng trở lên) theo đúng chỉ định và hướng dẫn của bác sĩ.'),
('D006', 'Sốt xuất huyết', 'Bệnh truyền nhiễm cấp tính do virus Dengue gây ra, lây truyền qua muỗi vằn (Aedes aegypti).', 'Sốt cao đột ngột (39-40°C) kéo dài 2-7 ngày, đau đầu dữ dội, đau nhức hốc mắt, đau cơ khớp. Có thể xuất hiện chấm xuất huyết dưới da, chảy máu cam, chảy máu chân răng.', 'Virus Dengue (có 4 type huyết thanh: DEN-1, DEN-2, DEN-3, DEN-4) do muỗi vằn đốt người bệnh rồi truyền virus sang người lành.', 'Diệt muỗi, lăng quăng (bọ gậy); ngủ màn (kể cả ban ngày); mặc quần áo dài tay; dọn dẹp nơi nước đọng quanh nhà; dùng kem chống muỗi.', 'Không có thuốc điều trị đặc hiệu. Chủ yếu là điều trị triệu chứng: hạ sốt bằng Paracetamol (tuyệt đối không dùng Aspirin, Ibuprofen), uống nhiều nước (Oresol), theo dõi dấu hiệu cảnh báo.'),
('D007', 'Sốt rét', 'Bệnh truyền nhiễm do ký sinh trùng Plasmodium gây ra, lây truyền qua vết đốt của muỗi Anopheles.', 'Sốt rét điển hình qua 3 giai đoạn: Rét run (ớn lạnh, run bần bật), Sốt cao (40-41°C, mặt đỏ, da khô), Vã mồ hôi (sốt giảm, mồ hôi ra nhiều). Cơn sốt có tính chu kỳ.', 'Ký sinh trùng Plasmodium (P. falciparum, P. vivax, P. malariae, P. ovale) do muỗi Anopheles truyền vào máu.', 'Ngủ màn tẩm hóa chất diệt muỗi, dùng kem xua muỗi, mặc quần áo che chắn, diệt muỗi và bọ gậy, uống thuốc phòng ngừa khi vào vùng sốt rét.', 'Sử dụng thuốc đặc trị sốt rét (như Artemisinin, Chloroquine...) theo phác đồ của Bộ Y tế.'),
('D008', 'Bệnh Tay Chân Miệng', 'Bệnh truyền nhiễm cấp tính do virus đường ruột gây ra, thường gặp ở trẻ em dưới 5 tuổi.', 'Sốt (nhẹ hoặc cao), đau họng, biếng ăn. Xuất hiện các bọng nước/vết loét ở niêm mạc miệng. Phát ban dạng phỏng nước ở lòng bàn tay, lòng bàn chân, đầu gối, mông.', 'Virus Enterovirus, phổ biến nhất là Coxsackievirus A16 và Enterovirus 71 (EV71). Lây qua đường tiêu hóa (tiếp xúc phân, dịch tiết) hoặc giọt bắn hô hấp.', 'Rửa tay thường xuyên cho trẻ và người chăm sóc. Vệ sinh đồ chơi, vật dụng. Không cho trẻ mút tay, bốc thức ăn. Cách ly trẻ bệnh tại nhà.', 'Không có thuốc đặc trị. Điều trị triệu chứng: hạ sốt, dùng thuốc bôi giảm đau rát, uống nhiều nước mát, ăn thức ăn mềm, lỏng. Theo dõi biến chứng.'),
('D009', 'Viêm Kết Mạc (Đau mắt đỏ)', 'Tình trạng viêm lớp màng trong suốt (kết mạc) bao phủ lòng trắng của mắt và mặt trong của mí mắt.', 'Mắt đỏ, cộm, ngứa, chảy nước mắt, có nhiều ghèn (dử mắt) màu vàng hoặc xanh (do vi khuẩn) hoặc trong, dính (do virus), nhạy cảm với ánh sáng, mí mắt sưng.', 'Virus (phổ biến nhất, rất dễ lây), vi khuẩn, hoặc dị ứng (phấn hoa, lông động vật, bụi).', 'Rửa tay thường xuyên, không dụi mắt, không dùng chung khăn mặt/đồ trang điểm mắt, tránh tiếp xúc gần với người bệnh, đeo kính bảo vệ khi ra ngoài.', 'Vệ sinh mắt bằng nước muối sinh lý. Nếu do virus, bệnh tự khỏi. Nếu do vi khuẩn, bác sĩ kê thuốc nhỏ mắt kháng sinh. Nếu do dị ứng, dùng thuốc chống dị ứng.'),
('D010', 'Bệnh Tiêu chảy cấp', 'Tình trạng đi ngoài phân lỏng hoặc tóe nước từ 3 lần trở lên trong 24 giờ, kéo dài không quá 14 ngày.', 'Đi ngoài phân lỏng nhiều lần, đau quặn bụng, nôn, sốt, mệt mỏi. Nguy cơ chính là mất nước và điện giải (khát nước, môi khô, mắt trũng, mệt lả).', 'Nhiễm trùng (virus như Rotavirus, vi khuẩn như E. coli, tả, lỵ) do ăn uống không hợp vệ sinh. Một số trường hợp do thuốc hoặc không dung nạp thực phẩm.', 'Ăn chín uống sôi, rửa tay trước khi ăn và sau khi đi vệ sinh, sử dụng nguồn nước sạch, xử lý phân an toàn, tiêm vắc-xin (Rotavirus, tả).', 'Quan trọng nhất là bù nước và điện giải (uống Oresol). Tiếp tục cho ăn (ăn thức ăn lỏng, dễ tiêu). Dùng thuốc theo chỉ định của bác sĩ.'),
('D011', 'Viêm dạ dày ruột', 'Tình trạng viêm nhiễm ở niêm mạc dạ dày và ruột non, thường gọi là ''ngộ độc thực phẩm'' hoặc ''cúm dạ dày''.', 'Nôn, buồn nôn, tiêu chảy (thường đột ngột), đau quặn bụng, có thể kèm sốt, ớn lạnh, mệt mỏi.', 'Thường do virus (Norovirus, Rotavirus) hoặc vi khuẩn (Salmonella, E. coli, Campylobacter) từ thực phẩm hoặc nước uống bị ô nhiễm.', 'Rửa tay kỹ, bảo quản và chế biến thực phẩm an toàn (ăn chín, uống sôi, tách riêng đồ sống và chín).', 'Bệnh thường tự khỏi. Quan trọng là bù nước và điện giải (Oresol) để tránh mất nước. Nghỉ ngơi. Ăn thức ăn nhạt, dễ tiêu (cháo, bánh mì nướng) khi triệu chứng thuyên giảm.'),
('D012', 'Thủy đậu', 'Bệnh truyền nhiễm cấp tính do virus Varicella-Zoster (VZV) gây ra, rất dễ lây lan.', 'Sốt nhẹ, mệt mỏi, chán ăn. Sau đó xuất hiện phát ban (nốt rạ): nốt đỏ -> nốt phỏng nước (rất ngứa) -> vỡ, đóng vảy. Mọc toàn thân.', 'Virus Varicella-Zoster. Lây qua đường hô hấp (giọt bắn) hoặc tiếp xúc trực tiếp với dịch từ nốt phỏng nước.', 'Tiêm vắc-xin phòng thủy đậu (biện pháp hiệu quả nhất). Cách ly người bệnh, tránh tiếp xúc với dịch từ nốt phỏng.', 'Điều trị triệu chứng: hạ sốt (Paracetamol), bôi dung dịch sát khuẩn (xanh methylen) lên nốt phỏng vỡ, giữ vệ sinh da, cắt móng tay (tránh gãi gây bội nhiễm).'),
('D013', 'Bệnh Tăng huyết áp', 'Tình trạng áp lực của máu tác động lên thành động mạch cao hơn mức bình thường một cách mạn tính. (Chỉ số huyết áp >= 140/90 mmHg).', 'Thường không có triệu chứng rõ ràng (nên gọi là ''kẻ giết người thầm lặng''). Một số người có thể bị đau đầu, chóng mặt, ù tai, hoa mắt, chảy máu cam.', 'Hầu hết là vô căn (nguyên phát). Yếu tố nguy cơ: tuổi tác, di truyền, thừa cân, béo phì, ăn mặn, hút thuốc lá, uống nhiều rượu bia, stress, lười vận động.', 'Duy trì cân nặng lý tưởng, chế độ ăn uống lành mạnh (giảm muối, tăng rau xanh), tập thể dục đều đặn, không hút thuốc, hạn chế rượu bia, kiểm soát căng thẳng.', 'Thay đổi lối sống. Dùng thuốc hạ huyết áp theo chỉ định của bác sĩ (thuốc lợi tiểu, chẹn beta, ức chế men chuyển...). Theo dõi huyết áp thường xuyên.'),
('D014', 'Bệnh Tim mạch vành', 'Bệnh lý xảy ra khi các động mạch vành (mạch máu nuôi tim) bị hẹp hoặc tắc nghẽn, thường do mảng xơ vữa, làm giảm lưu lượng máu đến cơ tim.', 'Đau thắt ngực (cảm giác đè nén, siết chặt ở ngực, có thể lan ra cánh tay, vai, cổ), khó thở, mệt mỏi, tim đập nhanh. Nặng nhất là nhồi máu cơ tim.', 'Xơ vữa động mạch (mảng bám cholesterol tích tụ). Yếu tố nguy cơ: tăng huyết áp, rối loạn mỡ máu (cao Cholesterol), đái tháo đường, hút thuốc, béo phì.', 'Kiểm soát tốt huyết áp, mỡ máu, đường huyết. Chế độ ăn lành mạnh (ít béo bão hòa, ít muối), không hút thuốc, tập thể dục, duy trì cân nặng hợp lý.', 'Thay đổi lối sống. Dùng thuốc (giãn mạch, giảm mỡ máu, chống đông máu). Can thiệp (nong mạch, đặt stent) hoặc phẫu thuật bắc cầu động mạch vành nếu cần.'),
('D015', 'Đái tháo đường', 'Bệnh rối loạn chuyển hóa mạn tính, đặc trưng bởi mức đường (glucose) trong máu luôn cao hơn bình thường.', '(Type 2 thường âm thầm) Cổ điển (Type 1): Ăn nhiều, uống nhiều, tiểu nhiều, gầy sút cân nhanh. Mệt mỏi, mờ mắt, vết thương lâu lành, nhiễm trùng da.', 'Type 1: Tuyến tụy không sản xuất insulin (thường do tự miễn). Type 2: Cơ thể kháng insulin hoặc sản xuất không đủ insulin (liên quan lối sống, béo phì).', '(Type 2) Duy trì cân nặng hợp lý, chế độ ăn lành mạnh (giảm đường, tinh bột, tăng chất xơ), tập thể dục thường xuyên, không hút thuốc.', '(Type 1) Tiêm insulin. (Type 2) Thay đổi lối sống, dùng thuốc uống hạ đường huyết, có thể cần tiêm insulin. Cần theo dõi đường huyết và khám định kỳ.'),
('D016', 'Ung thư', 'Nhóm bệnh lý đặc trưng bởi sự phát triển không kiểm soát của các tế bào bất thường, chúng xâm lấn và phá hủy các mô cơ thể, và có thể di căn.', 'Rất đa dạng. Dấu hiệu cảnh báo chung: sụt cân không rõ nguyên nhân, mệt mỏi, sốt kéo dài, thay đổi thói quen đại/tiểu tiện, vết loét không lành, ho dai dẳng, xuất huyết bất thường, nổi u cục.', 'Đột biến gen trong tế bào. Yếu tố nguy cơ: di truyền, hút thuốc, uống rượu, phơi nhiễm hóa chất/bức xạ, nhiễm trùng (HPV, viêm gan B, C), béo phì.', 'Không hút thuốc, hạn chế rượu bia, ăn uống lành mạnh, tập thể dục, duy trì cân nặng, tiêm vắc-xin (HPV, viêm gan B), tránh nắng gắt, tầm soát ung thư định kỳ.', 'Tùy loại và giai đoạn. Các phương pháp chính: Phẫu thuật (loại bỏ khối u), Xạ trị (dùng tia X tiêu diệt tế bào ung thư), Hóa trị (dùng thuốc), Liệu pháp miễn dịch.'),
('D017', 'Bệnh Phổi tắc nghẽn mạn tính (COPD)', 'Bệnh lý hô hấp mạn tính đặc trưng bởi sự tắc nghẽn luồng khí thở ra không hồi phục hoàn toàn, thường do viêm phế quản mạn và khí phế thũng.', 'Khó thở (nhất là khi gắng sức), ho mạn tính, khạc đờm mạn tính, thở khò khè, mệt mỏi, sụt cân (giai đoạn muộn).', 'Hút thuốc lá (kể cả thụ động) là nguyên nhân hàng đầu. Phơi nhiễm khói bụi, ô nhiễm không khí, hóa chất nghề nghiệp.', 'Ngưng hút thuốc lá tuyệt đối. Tránh xa môi trường khói bụi, ô nhiễm. Tiêm vắc-xin cúm và phế cầu hàng năm.', 'Không thể chữa khỏi. Bỏ hút thuốc. Dùng thuốc giãn phế quản (dạng hít/xịt), thuốc kháng viêm (corticosteroid dạng hít), liệu pháp oxy, phục hồi chức năng hô hấp.'),
('D018', 'Viêm loét dạ dày và Tá tràng', 'Tình trạng niêm mạc dạ dày hoặc tá tràng (phần đầu ruột non) bị tổn thương, hình thành các vết loét do acid và men tiêu hóa (pepsin) gây ra.', 'Đau bụng vùng thượng vị (có thể đau âm ỉ hoặc quặn, đau khi đói hoặc sau khi ăn), ợ hơi, ợ chua, buồn nôn, nôn, đầy bụng, khó tiêu. Biến chứng: xuất huyết tiêu hóa, thủng.', 'Nhiễm vi khuẩn Helicobacter pylori (HP) là nguyên nhân chính. Lạm dụng thuốc kháng viêm không steroid (NSAIDs như Aspirin, Ibuprofen). Stress, rượu bia, thuốc lá.', 'Vệ sinh ăn uống (phòng lây nhiễm HP), sử dụng thuốc NSAIDs thận trọng, hạn chế rượu bia, thuốc lá, giảm căng thẳng.', 'Dùng thuốc giảm tiết acid (PPI), thuốc kháng sinh (nếu có HP), thuốc trung hòa acid (antacid). Thay đổi lối sống: ăn uống đúng giờ, tránh đồ chua cay, rượu bia.'),
('D019', 'Bệnh Gút (Gout)', 'Bệnh viêm khớp do rối loạn chuyển hóa acid uric, làm nồng độ acid uric trong máu tăng cao, dẫn đến lắng đọng tinh thể urat ở khớp và các mô.', 'Cơn Gút cấp: Sưng, nóng, đỏ, đau dữ dội (thường ở khớp ngón chân cái), khởi phát đột ngột. Giai đoạn mạn: xuất hiện hạt tophi (cục u) dưới da, viêm khớp mạn tính.', 'Tăng sản xuất hoặc giảm đào thải acid uric. Yếu tố nguy cơ: Di truyền, nam giới, tuổi tác, béo phì, uống nhiều rượu bia, ăn nhiều thực phẩm giàu purin (nội tạng, hải sản, thịt đỏ).', 'Chế độ ăn uống hạn chế purin, hạn chế rượu bia (đặc biệt là bia), uống nhiều nước, duy trì cân nặng hợp lý, tập thể dục.', '(Cơn cấp) Thuốc kháng viêm (NSAIDs, Colchicine, Corticosteroid). (Mạn tính) Thuốc hạ acid uric máu (Allopurinol, Febuxostat) kết hợp thay đổi lối sống.'),
('D020', 'Viêm khớp mạn tính', 'Thuật ngữ chung chỉ tình trạng viêm kéo dài ở một hoặc nhiều khớp. Hai loại phổ biến là Thoái hóa khớp (OA) và Viêm khớp dạng thấp (RA).', 'Đau khớp (tăng khi vận động - OA; đau cả khi nghỉ, cứng khớp buổi sáng - RA), sưng khớp, cứng khớp, giảm biên độ vận động, biến dạng khớp (giai đoạn muộn).', '(OA) Mòn sụn khớp do tuổi tác, chấn thương, béo phì. (RA) Rối loạn tự miễn (hệ miễn dịch tự tấn công màng hoạt dịch khớp).', 'Duy trì cân nặng lý tưởng, tập thể dục hợp lý (tránh chấn thương), chế độ ăn chống viêm (giàu omega-3, rau xanh), không hút thuốc.', 'Không chữa khỏi. Điều trị giảm đau, kháng viêm (NSAIDs, Corticoid), vật lý trị liệu. (RA) cần dùng thuốc điều trị cơ bản (DMARDs). Phẫu thuật (thay khớp) khi khớp hỏng nặng.');
